insert into public.catalogo (tipo, nome, dados, resumo, fonte) values
('origem', 'Ferido por Ritual', '{"pericias": "Ocultismo e uma perícia pelo elemento (Sangue: Fortitude; Morte: Vontade; Conhecimento ou Energia: Reflexos)", "subtipo": "Poder: Mácula Ritualística"}'::jsonb, 'Aprende um ritual de 1º círculo do elemento que o marcou e o conjura de graça uma vez por cena (fora do limite), mas sofre –1 dado contra efeitos desse elemento.', 'Arquivos Secretos 1, p. 43'),
('origem', 'Transtornado Arrependido', '{"pericias": "Luta e Ocultismo", "subtipo": "Poder: Sofrimento de Sangue"}'::jsonb, 'Resistência 2 a dano mental, +1 para cada dois rituais ou poderes de Sangue; o descanso é sempre uma categoria pior.', 'Arquivos Secretos 1, p. 43'),
('uso_pericia', 'Blindar a Mente', '{"subtipo": "Ocultismo"}'::jsonb, 'Veterano, DT 20: ação completa e 1 PE para +5 no próximo teste de Vontade da cena. Num aliado: DT 25 e ele testa Vontade DT 20 ou perde 1d4 SAN.', 'Arquivos Secretos 1, p. 43'),
('poder_classe', 'Ritual Intenso', '{"classe": "Ocultista", "prerequisitos": "Pre 2"}'::jsonb, 'Soma Presença no dano e na cura dos seus rituais.', 'Arquivos Secretos 1, p. 44'),
('poder_classe', 'Acostumado a Maldição de (Elemento)', '{"classe": "Ocultista", "prerequisitos": "Int 2, conjurar ritual de 2º círculo do elemento"}'::jsonb, 'Não perde Sanidade pelo preço da maldição de itens do elemento escolhido (outros efeitos continuam).', 'Arquivos Secretos 1, p. 44'),
('poder_classe', 'Saúde Sobrenatural', '{"classe": "Ocultista", "prerequisitos": "Int 2, Pre 2, conjurar ritual de 1º círculo"}'::jsonb, 'Uma vez por cena, movimento e 3 PE: PV temporários iguais a Presença x10.', 'Arquivos Secretos 1, p. 44'),
('poder_classe', 'Reter Ritual de Combate', '{"classe": "Ocultista", "prerequisitos": "Int 2, conjurar ritual de 1º círculo"}'::jsonb, 'Com a regra opcional Reter Ritual, pode mudar para cena a duração de rituais retidos (1 PE por ritual ao perder a retenção).', 'Arquivos Secretos 1, p. 44'),
('habilidade_trilha', 'Identificação Macabra', '{"classe": "Ocultista", "trilha": "Maledictólogo", "nex": 10}'::jsonb, '1 PE: +1d10 para identificar itens amaldiçoados ou rituais; identificar item como ação completa sofre só –1 dado.', 'Arquivos Secretos 1, p. 45'),
('habilidade_trilha', 'Compreensão de Maldições', '{"classe": "Ocultista", "trilha": "Maledictólogo", "nex": 40}'::jsonb, 'No interlúdio, 3 PE e Ocultismo (DT 10 +5 por categoria): aprende o ritual de um item ou transfere as maldições dele para outro item ou uma tatuagem. Custa Sanidade.', 'Arquivos Secretos 1, p. 45'),
('habilidade_trilha', 'Reproduzir Maldição', '{"classe": "Ocultista", "trilha": "Maledictólogo", "nex": 65}'::jsonb, 'Memoriza uma maldição conhecida e a aplica a outro item até o fim da missão (3 PE, Ocultismo, custa Sanidade).', 'Arquivos Secretos 1, p. 45'),
('habilidade_trilha', 'Maldição Suprema', '{"classe": "Ocultista", "trilha": "Maledictólogo", "nex": 99}'::jsonb, 'Ao reproduzir maldições, trata o item como três categorias abaixo.', 'Arquivos Secretos 1, p. 45'),
('poder_geral', '(Habilidade) Aprimorada', '{}'::jsonb, 'A DT de uma habilidade ou ritual sobe +2 (pode escolher duas vezes o mesmo, total +5).', 'Arquivos Secretos 1, p. 46'),
('poder_geral', 'Cicatrizes Expostas', '{"prerequisitos": "Ter cicatrizes"}'::jsonb, 'Movimento para expor a cicatriz: +1d8 de dano, mas –1 dado em Vontade e em testes que pedem calma, até o fim da cena.', 'Arquivos Secretos 1, p. 46'),
('poder_geral', 'Instintos Urbanos', '{"prerequisitos": "Agi 2"}'::jsonb, 'Treino em Crime (ou +2); Crime DT 20 num lugar fechado revela rota de fuga: movimento extra ao fugir e +2 de Defesa.', 'Arquivos Secretos 1, p. 46'),
('poder_geral', 'Curiosidade Oculta', '{"prerequisitos": "Int 2"}'::jsonb, 'Treino em Ocultismo (ou +2) e 2 PE para usar Ocultismo no lugar de Vontade.', 'Arquivos Secretos 1, p. 46'),
('poder_geral', 'Especialista Esotérico', '{"prerequisitos": "Int 3, conjurar ritual de 2º círculo, Domínio Esotérico"}'::jsonb, 'Combina até três catalisadores ritualísticos num mesmo ritual.', 'Arquivos Secretos 1, p. 46'),
('poder_paranormal', 'Ferro Maculado', '{"elemento": "Sangue", "afinidade": "O dano vira +1d8."}'::jsonb, 'Movimento e 2 PV: um projétil causa +1d6 de Sangue uma vez.', 'Arquivos Secretos 1, p. 47'),
('poder_paranormal', 'Sangue Corrosivo', '{"elemento": "Sangue", "afinidade": "O dano vira 2d10."}'::jsonb, 'Movimento e 1 PE: até o fim da cena, quem o fere estando adjacente sofre 1d10 de Sangue.', 'Arquivos Secretos 1, p. 47'),
('poder_paranormal', 'Placas Sanguinolentas', '{"elemento": "Sangue", "afinidade": "O bônus vira círculo +2.", "prerequisitos": "Conjurar ritual de Sangue"}'::jsonb, 'Ao conjurar um ritual de Sangue, Defesa + círculo do ritual até seu próximo turno.', 'Arquivos Secretos 1, p. 47'),
('poder_paranormal', 'Sangue Prazeroso', '{"elemento": "Sangue", "afinidade": "Também +20 PV temporários uma vez por cena.", "prerequisitos": "Sangue 1"}'::jsonb, 'Machucado: resistência a dano 5.', 'Arquivos Secretos 1, p. 47'),
('ritual', 'Passagem de Conhecimento', '{"elemento": "Sangue e Conhecimento", "circulo": 2, "custo_pe": 3, "execucao": "completa", "alcance": "toque", "alvo": "1 pessoa", "duracao": "cena", "resistencia": "Vontade evita", "discente": "+3 PE: alcance curto e dura 1 dia (2º círculo).", "verdadeiro": "+7 PE: alcance médio e permanente (4º círculo e afinidade)."}'::jsonb, 'Domina o corpo do alvo ou troca de corpo com ele (cada um usa os atributos físicos do outro). Morte de um corpo prende ou mata quem está nele.', 'Arquivos Secretos 1, p. 48'),
('ritual', 'Passagem de Conhecimento Expandido', '{"elemento": "Sangue e Conhecimento", "circulo": 4, "custo_pe": 10, "execucao": "1 dia", "alcance": "curto", "alvo": "10 pessoas", "duracao": "veja texto"}'::jsonb, 'Transfere a consciência de cinco voluntários para cinco corpos inconscientes. Exige conhecer Passagem de Conhecimento.', 'Arquivos Secretos 1, p. 50'),
('item', 'Agrupador Ritualístico', '{"categoria": "II", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Segura até quatro componentes ou catalisadores, que contam como empunhados.', 'Arquivos Secretos 1, p. 54'),
('item', 'Amuleto Sinalizador de (Elemento)', '{"categoria": "II", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Dá um sinal visível quando uma criatura do elemento entra em alcance longo, mesmo atrás de paredes.', 'Arquivos Secretos 1, p. 54'),
('item', 'Rubra', '{"categoria": "II", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Droga paranormal: +5 em Força, Agilidade e Vigor e 10 PV temporários; depois perde atributos físicos até dormir e arrisca insanidade.', 'Arquivos Secretos 1, p. 54'),
('item_amaldicoado', 'Arpão do Pescador', '{"categoria": "III", "espacos": 1, "elemento": "Sangue"}'::jsonb, 'Arma simples arremessável: 1d8 perfuração +1d12 Sangue, crítico x3; o alvo atingido no arremesso fica lento até arrancar.', 'Arquivos Secretos 1, p. 55'),
('item_amaldicoado', 'Combustível de Sangue', '{"categoria": "III", "espacos": 1, "elemento": "Sangue"}'::jsonb, 'Munição de lança-chamas ou galão: dano vira Sangue e os dados sobem uma categoria.', 'Arquivos Secretos 1, p. 55'),
('item_amaldicoado', 'Marreta Transtornada', '{"categoria": "IV", "espacos": 2, "elemento": "Sangue"}'::jsonb, 'Arma tática de duas mãos: 2d10 impacto +2d12 Sangue, crítico x4; custa 1d6 PV para empunhar ou atacar e pode quebrar ossos no crítico.', 'Arquivos Secretos 1, p. 55'),
('item', 'Kit de Escalada', '{"categoria": "I", "espacos": 2, "subtipo": "Recurso"}'::jsonb, 'Utensílio: +2 em Atletismo para escalar.', 'Arquivos Secretos 2, p. 21'),
('item', 'Bandagem', '{"categoria": "I", "espacos": 0.5, "subtipo": "Recurso"}'::jsonb, 'Ação padrão, consome: cura 2d4+2 PV e remove sangrando (você ou alguém adjacente).', 'Arquivos Secretos 2, p. 21'),
('item', 'Bússola', '{"categoria": "I", "espacos": 1, "subtipo": "Recurso"}'::jsonb, 'Utensílio: +2 em Sobrevivência para se orientar.', 'Arquivos Secretos 2, p. 21'),
('item', 'Pedra de Amolar', '{"categoria": "I", "espacos": 0.5, "subtipo": "Recurso"}'::jsonb, 'Interlúdio: uma arma de corte ou perfuração causa +1d4 na próxima cena em que for usada.', 'Arquivos Secretos 2, p. 21'),
('item', 'Caixa de Ferramentas', '{"categoria": "I", "espacos": 2, "subtipo": "Recurso"}'::jsonb, 'Utensílio: +2 em Profissão quando as ferramentas fizerem sentido.', 'Arquivos Secretos 2, p. 21'),
('item', 'Dose de Álcool', '{"categoria": "I", "espacos": 0.5, "subtipo": "Recurso"}'::jsonb, '+2 contra infecções e doenças por contato; com bandagem, a cura vira 2d8+2. Inflamável.', 'Arquivos Secretos 2, p. 21'),
('item', 'Incenso', '{"categoria": "I", "espacos": 0.5, "subtipo": "Recurso"}'::jsonb, 'Interlúdio: todos na cena recuperam 1d4 PE (uma vez por dia).', 'Arquivos Secretos 2, p. 21'),
('ritual', 'Mapa Sanguíneo', '{"elemento": "Sangue", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "toque", "alvo": "1 superfície", "duracao": "cena", "resistencia": "Vontade evita", "discente": "+3 PE: também mostra a condição de saúde de cada um."}'::jsonb, 'Desenha com sangue um mapa que mostra, em tempo real, onde estão todos os seres num raio de 1km.', 'Arquivos Secretos 2, p. 65'),
('ritual', 'Capturar Momento', '{"elemento": "Morte", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "médio", "alvo": "esfera de 18m de raio", "duracao": "permanente até ser dissipado", "discente": "+3 PE: pode explodir o símbolo (4d8 de Morte em quem ele capta, Fortitude reduz).", "verdadeiro": "+7 PE: como discente, com 8d8 (3º círculo)."}'::jsonb, 'Marca um local com um símbolo invisível que capta imagens e sons; você pode ver e ouvir por ele à distância.', 'Arquivos Secretos 2, p. 66'),
('ritual', 'Labirinto Mental', '{"elemento": "Conhecimento", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "médio", "alvo": "1 pessoa", "duracao": "1d4 rodadas", "resistencia": "Vontade evita", "discente": "+3 PE: alcance longo.", "verdadeiro": "+7 PE: alcance longo e dura a cena (3º círculo)."}'::jsonb, 'Prende a mente do alvo: ele gasta as ações andando em direções aleatórias; testa de novo a cada turno.', 'Arquivos Secretos 2, p. 66'),
('ritual', 'Rajada Caótica', '{"elemento": "Energia", "circulo": 2, "custo_pe": 3, "execucao": "padrão", "alcance": "médio", "alvo": "1 ser", "duracao": "instantânea", "resistencia": "Reflexos reduz à metade", "discente": "+3 PE: 8d8.", "verdadeiro": "+7 PE: 8d10 e pode disparar de novo a cada turno pela cena (3º círculo)."}'::jsonb, 'Raio de 8d6 de Energia.', 'Arquivos Secretos 2, p. 67'),
('item_amaldicoado', 'A Antena', '{"categoria": "IV", "espacos": 2, "elemento": "Medo"}'::jsonb, 'Arma improvisada de duas mãos (1d6 impacto); +3 na DT dos seus rituais e guarda um ritual para soltar depois com ação padrão.', 'Arquivos Secretos 2, p. 67'),
('poder_classe', 'Dominar Habilidade Ritualística', '{"classe": "Ocultista", "prerequisitos": "Int 3, treinado em Ocultismo, conjurar rituais"}'::jsonb, 'Aprende uma habilidade de trilha de ocultista de outra trilha, respeitando o NEX. Até três vezes.', 'Arquivos Secretos 2, p. 75'),
('poder_geral', 'Prática com Materiais Ritualísticos', '{"prerequisitos": "Int 2, treinado em Ocultismo, conjurar rituais"}'::jsonb, 'Em conjurações complexas, não sofre a penalidade por materiais específicos da entidade.', 'Arquivos Secretos 2, p. 74'),
('item', 'Catalisador Sofisticado e Horrorizado', '{"categoria": "III", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Vestível, não se gasta: uma vez por cena recebe 3d6 para somar (um por ritual) ao dano, à cura ou à DT de rituais.', 'Arquivos Secretos 2, p. 75'),
('poder_geral', 'Arte da Música Macabra', '{"prerequisitos": "Int 2 ou Pre 2, treinado em Ocultismo, conjurar rituais"}'::jsonb, 'Ação padrão e 2 PE: um ser que ouve você ganha +5 no próximo dano, +2 na margem, +5 no ataque ou +9m de alcance.', 'Arquivos Secretos 2, p. 83'),
('poder_geral', 'Sintonização Mental com Proteção', '{"prerequisitos": "Int 2 ou Pre 2, treinado em Ocultismo, conjurar rituais"}'::jsonb, 'Interlúdio e 3 PE: a proteção vestida usa outro atributo no lugar de Agilidade para a Defesa.', 'Arquivos Secretos 2, p. 83'),
('poder_geral', 'Sintonização Mental com Arma', '{"prerequisitos": "Int 2 ou Pre 2, treinado em Ocultismo, conjurar rituais"}'::jsonb, 'Interlúdio e 3 PE: a arma empunhada usa o atributo escolhido para ataque e dano.', 'Arquivos Secretos 2, p. 83'),
('poder_classe', 'Marteladas', '{"classe": "Combatente", "prerequisitos": "For 2, treinado em Luta, Artista Marcial"}'::jsonb, 'Ação completa e 3 PE: três ataques desarmados somados como um só dano (Fortitude reduz).', 'Arquivos Secretos 2, p. 87'),
('poder_geral', 'Movimentação Tática', '{"prerequisitos": "For 2, treinado em Atletismo e Tática"}'::jsonb, '1 PE: dobra o deslocamento ao ir para cobertura ou para um inimigo.', 'Arquivos Secretos 2, p. 87'),
('poder_geral', 'Sentido Tático (Militar)', '{"prerequisitos": "Pre 2, treinado em Percepção e Tática"}'::jsonb, 'Imune a desprevenido; ao causar dano, 2 PE para o alvo falhar em Furtividade contra você por 1 rodada.', 'Arquivos Secretos 2, p. 87'),
('poder_classe', 'Flagelo Bem Aproveitado', '{"classe": "Ocultista", "prerequisitos": "Escolhido pelo Outro Lado, Poder do Flagelo"}'::jsonb, 'Poder do Flagelo passa a custar 1 PV por PE.', 'Arquivos Secretos 3, p. 108'),
('poder_classe', 'Recuperação Flagelante', '{"classe": "Ocultista", "prerequisitos": "Escolhido pelo Outro Lado, Poder do Flagelo"}'::jsonb, 'Uma vez entre interlúdios, recupera por outros meios os PV gastos com Poder do Flagelo (até 3 usos se repetido).', 'Arquivos Secretos 3, p. 108'),
('poder_classe', 'Guardião da Tropa', '{"classe": "Combatente", "prerequisitos": "Ataque Especial, Casca Grossa"}'::jsonb, 'Reação e 2 PE: recebe no lugar de um aliado adjacente um ataque ou efeito de alvo único; se resistir, recupera 1 SAN.', 'Arquivos Secretos 3, p. 108'),
('poder_classe', 'Vitalidade Sofrida', '{"classe": "Combatente", "prerequisitos": "Ataque Especial"}'::jsonb, 'PV da classe passam a 24+Vig iniciais e 6+Vig por NEX, inclusive retroativamente.', 'Arquivos Secretos 3, p. 108'),
('poder_geral', 'Ambidestria', '{"prerequisitos": "For 2 ou Agi 2, treinado em Luta"}'::jsonb, 'Ataca com duas armas ao agredir (–1d20 nos ataques); com Combater com Duas Armas, sem penalidade e com armas de uma mão.', 'Arquivos Secretos 3, p. 108'),
('poder_geral', 'Entrada Triunfal', '{"prerequisitos": "Pre 2"}'::jsonb, 'Uma vez por sessão, ao anunciar sua chegada, +1d20 no primeiro teste no ambiente (pode passar para um aliado).', 'Arquivos Secretos 3, p. 109'),
('poder_geral', 'Papinho Sedutor', '{"prerequisitos": "Pre 2"}'::jsonb, '1 PE: +5 num teste de Presença para seduzir; quem se apaixona pode virar problema.', 'Arquivos Secretos 3, p. 109'),
('poder_paranormal', 'Instrumento Elétrico de Combate', '{"elemento": "Energia", "afinidade": "Atinge todos os alvos escolhidos em alcance curto."}'::jsonb, 'Transforma um instrumento que você toca numa arma de Energia de duas mãos: ataque com Artes em alcance curto, 2d8 + Presença.', 'Arquivos Secretos 3, p. 109'),
('poder_paranormal', 'Conhecimento de Direção Precognitiva', '{"elemento": "Conhecimento", "afinidade": "O bônus vira +10."}'::jsonb, '+5 em Percepção ou Sobrevivência para se orientar até um lugar, mesmo sem conhecê-lo.', 'Arquivos Secretos 3, p. 109'),
('item', 'Bloody Mary Batizada', '{"categoria": "II", "espacos": 1, "subtipo": "Geral"}'::jsonb, 'Beber remove uma condição mental ou de medo, mas causa 2d4 de dano mental.', 'Arquivos Secretos 3, p. 112'),
('arma', 'Garra do Harpia', '{"categoria": "I", "espacos": 2, "subtipo": "Táticas, Corpo a Corpo – Duas Mãos", "dano": "2d8", "critico": "19", "margem": 19, "multiplicador": 2, "tipo_dano": "corte", "alcance": "Curto"}'::jsonb, 'Arma tática ágil de duas mãos, arremessável; ao causar dano, 2 PE para agarrar. Item único.', 'Arquivos Secretos 3, p. 112'),
('item', 'Paçoca', '{"categoria": "0", "espacos": 0.5, "subtipo": "Geral"}'::jsonb, 'Prato rápido; uma vez por dia, em ocasiões especiais, recupera 1d8+1 PV, PE e SAN.', 'Arquivos Secretos 3, p. 112'),
('item', 'Crânio Dominador', '{"categoria": "III", "espacos": 1, "subtipo": "Paranormal"}'::jsonb, 'Ação padrão e 2 PE: correntes paralisam até dois alvos em alcance curto (Reflexos evita). Uma vez a cada 24h.', 'Arquivos Secretos 3, p. 113'),
('item', 'Gaiola do Corvo', '{"categoria": "IV", "espacos": 2, "subtipo": "Paranormal"}'::jsonb, 'Aberta no chão, cobre 18m de Lodo: terreno difícil e 3d10 de Morte por rodada; quem cai morrendo vira cinzas.', 'Arquivos Secretos 3, p. 113'),
('item_amaldicoado', 'Camiseta Psikolera', '{"categoria": "II", "espacos": 1, "elemento": "Sangue"}'::jsonb, 'Vestimenta: machucado, seu dano ganha +2d8 de Sangue.', 'Arquivos Secretos 3, p. 114'),
('item_amaldicoado', 'Dupla Obsessiva', '{"categoria": "III", "espacos": 2, "elemento": "Sangue"}'::jsonb, 'Maça e florete amaldiçoados (com dano extra de Sangue); ataca com as duas e pode receber ataques por um aliado.', 'Arquivos Secretos 3, p. 114'),
('item_amaldicoado', 'Armadura de Guevara (Couraças)', '{"categoria": "III", "espacos": 0, "elemento": "Sangue"}'::jsonb, 'Proteção pesada de Sangue: Defesa +10 (cresce até +20), 0 espaços, RD física 5 e Sangue 10, vulnerável a Morte; pode dominar o usuário.', 'Arquivos Secretos 3, p. 115'),
('origem', 'Influencer Paranormal', '{"pericias": "Enganação e Tecnologia", "subtipo": "Poder: Quem Não Arrisca, Não Petisca"}'::jsonb, '+2 para resistir a condições mentais e de medo; ao falhar num desses testes, +1d20 no próximo teste da cena.', 'Arquivos Secretos 4, p. 64'),
('origem', 'Caçador de Recompensas', '{"pericias": "Crime e Investigação", "subtipo": "Poder: Registrar o Paranormal"}'::jsonb, 'Uma vez por cena, ação padrão e 2 PE para registrar uma criatura ou ritual; no interlúdio, o registro dá bônus para identificar a criatura ou deixa você conjurar o ritual até o próximo interlúdio.', 'Arquivos Secretos 4, p. 64'),
('uso_pericia', 'Obter Informações', '{"subtipo": "Tecnologia"}'::jsonb, 'DT 5, ação completa: pesquisa rápida na internet sobre um lugar ou pessoa; uma informação, +1 a cada 5 pontos acima da DT.', 'Arquivos Secretos 4, p. 64'),
('poder_classe', 'Chuva de Balas', '{"classe": "Combatente"}'::jsonb, 'Pacotes de munição duram o dobro e rajadas causam dois dados extras de dano.', 'Arquivos Secretos 4, p. 65'),
('poder_classe', 'Combatente Esforçado', '{"classe": "Combatente", "prerequisitos": "For 3 ou Vig 3"}'::jsonb, '+1 PE por NEX.', 'Arquivos Secretos 4, p. 65'),
('poder_classe', 'Treinamento Militarizado', '{"classe": "Combatente"}'::jsonb, 'Exercitar-se no interlúdio não gasta ação e o bônus vira +1d8 (também usável no dano).', 'Arquivos Secretos 4, p. 65'),
('poder_classe', 'Análise Conturbada', '{"classe": "Especialista"}'::jsonb, 'Na investigação, ação padrão: quem aceitar ouvir suas teorias rola 1d6 e ganha isso em testes de Int e Pre na cena, mas perde o mesmo em SAN.', 'Arquivos Secretos 4, p. 65'),
('poder_classe', 'Profissão Perigo', '{"classe": "Especialista"}'::jsonb, 'Ação completa e 4 PE: desmonta um item e o transforma num item operacional de categoria e espaços até iguais. Três vezes por missão.', 'Arquivos Secretos 4, p. 65'),
('poder_classe', 'Quase Novo', '{"classe": "Especialista"}'::jsonb, 'Na manutenção do interlúdio, o item ganha +10 PV e uma modificação temporária até o próximo interlúdio.', 'Arquivos Secretos 4, p. 65'),
('poder_classe', 'Terrores Noturnos', '{"classe": "Ocultista"}'::jsonb, 'Ao dormir, 1d100: acima de 50, +2 PE; até 50, descanso precário e –1d4 SAN, mas pode usar uma vez um poder paranormal ou ritual que cumpra.', 'Arquivos Secretos 4, p. 66'),
('poder_classe', 'Explorador da Névoa', '{"classe": "Ocultista"}'::jsonb, 'Uma vez por cena, 2 PE para sentir o estado da Membrana; se danificada, perde 1 SAN e seus rituais custam 1 PE a menos.', 'Arquivos Secretos 4, p. 66'),
('poder_geral', 'Sinestesia Paranormal', '{}'::jsonb, 'Com a Membrana danificada, perde 1d6 SAN e troca os atributos de dois pares de perícias até sair da área.', 'Arquivos Secretos 4, p. 66'),
('poder_geral', 'Gororoba', '{}'::jsonb, 'No interlúdio, alimenta-se uma vez sem gastar ação nem precisar de comida.', 'Arquivos Secretos 4, p. 66'),
('poder_geral', 'Ruído Branco', '{"prerequisitos": "Int 3"}'::jsonb, 'Em ambientes movimentados, +1d6 em Investigação e Percepção; uma vez por cena, 1 PE para ouvir uma conversa útil.', 'Arquivos Secretos 4, p. 66'),
('poder_geral', 'Uma Última Olhada', '{}'::jsonb, 'Uma vez por cena, 2 PE na última rodada da investigação: o grupo ganha mais uma rodada.', 'Arquivos Secretos 4, p. 67'),
('poder_paranormal', 'Sobrepor Imprevisível', '{"elemento": "Energia", "afinidade": "Rola 2d20 e escolhe."}'::jsonb, 'Uma vez por rodada, no início, reação: rola 1d20 e soma (par) ou subtrai (ímpar) da iniciativa.', 'Arquivos Secretos 4, p. 67'),
('poder_paranormal', 'Foco Gravitacional', '{"elemento": "Energia", "afinidade": "A chance cumulativa cai para 5%."}'::jsonb, '2 PE: voo 9m até o fim do turno; cada uso extra na missão tem 10% cumulativos de falhar e cair (4d6).', 'Arquivos Secretos 4, p. 67'),
('poder_paranormal', 'Traço de Inconsistência', '{"elemento": "Energia", "afinidade": "Nunca aparece em imagens digitais e sua voz sai distorcida em gravações."}'::jsonb, 'Reação e 2 PE: sua identidade some das imagens digitais capturadas naquele momento.', 'Arquivos Secretos 4, p. 67'),
('ritual', 'Backup', '{"elemento": "Energia", "circulo": 2, "custo_pe": 3, "execucao": "completa", "alcance": "curto", "alvo": "veja texto", "duracao": "1 dia", "discente": "+3 PE: permanente e pode ver e ouvir pela cópia (3º círculo).", "verdadeiro": "+7 PE: também fala por ela, muda a aparência e pode explodir 6d6 ao trocar (4º círculo e afinidade)."}'::jsonb, 'Cria uma cópia de Energia sua num raio de 5km; reação para trocar de lugar com ela (perde 2d4 SAN). Dano na cópia dissipa.', 'Arquivos Secretos 4, p. 68'),
('habilidade_trilha', 'Meus Bebês', '{"classe": "Especialista", "trilha": "Granadeiro Blaster", "nex": 10}'::jsonb, 'Treino em Profissão (químico) ou +5; começa a missão com explosivos autorais (um a mais por habilidade da trilha), uma categoria abaixo.', 'Arquivos Secretos 4, p. 69'),
('habilidade_trilha', 'O Calor do Momento', '{"classe": "Especialista", "trilha": "Granadeiro Blaster", "nex": 40}'::jsonb, 'Uma vez por cena, ação padrão e PE para improvisar um explosivo autoral; usa granadas 40mm como arremessáveis.', 'Arquivos Secretos 4, p. 69'),
('habilidade_trilha', 'Fogo Amigo', '{"classe": "Especialista", "trilha": "Granadeiro Blaster", "nex": 65}'::jsonb, 'Ganha Perito em Explosivos (ou melhora); áreas dos seus explosivos crescem +6m.', 'Arquivos Secretos 4, p. 70'),
('habilidade_trilha', 'Memória Muscular', '{"classe": "Especialista", "trilha": "Granadeiro Blaster", "nex": 99}'::jsonb, 'Saca explosivos autorais como ação livre, usa-os como movimento por 4 PE e eles causam o dobro de dados.', 'Arquivos Secretos 4, p. 70'),
('item_amaldicoado', 'Granada Ctrl+C Ctrl+V', '{"categoria": "II", "espacos": 1, "elemento": "Energia"}'::jsonb, 'Granada de 8d6 de Energia em 6m; a cada par num d4, explode de novo em outro ponto (até quatro vezes).', 'Arquivos Secretos 4, p. 70'),
('item', 'Granada de Gás Lacrimogêneo', '{"categoria": "I", "espacos": 1, "subtipo": "Explosivo"}'::jsonb, 'Raio de 6m: 4d6 químico, enjoado e asfixiado (Fortitude reduz e evita o enjoo).', 'Arquivos Secretos 4, p. 70'),
('item', 'Granada de Tinta', '{"categoria": "0", "espacos": 1, "subtipo": "Explosivo"}'::jsonb, 'Raio de 6m: alvos ficam vulneráveis e com –2d20 em Furtividade na cena (Reflexos evita).', 'Arquivos Secretos 4, p. 70'),
('arma', 'Lançador de Granadas', '{"categoria": "II", "espacos": 2, "subtipo": "Pesadas, À Distância – Duas Mãos", "alcance": "Longo"}'::jsonb, 'Arma de fogo pesada de duas mãos, alcance longo; dispara granadas 40mm (até 6 carregadas).', 'Arquivos Secretos 4, p. 71'),
('modificacao', 'Adesiva', '{"subtipo": "Granadas"}'::jsonb, 'A granada gruda no alvo atingido, que falha nos testes contra ela.', 'Arquivos Secretos 4, p. 71'),
('modificacao', 'Dupla', '{"subtipo": "Granadas"}'::jsonb, 'A granada ganha o efeito de outra granada de categoria igual ou menor.', 'Arquivos Secretos 4, p. 71'),
('modificacao', 'Programada', '{"subtipo": "Granadas"}'::jsonb, 'Você define em quantos turnos a granada explode.', 'Arquivos Secretos 4, p. 71'),
('municao', 'Granada 40mm', '{"espacos": 1}'::jsonb, 'Granada para lançador; cada uma dura um disparo.', 'Arquivos Secretos 4, p. 71'),
('origem', 'Ufólogo', '{"pericias": "Ciências e Ocultismo", "subtipo": "Poder: Minha Teoria Absurda"}'::jsonb, 'Uma vez por cena de interlúdio, apresenta uma teoria ao grupo: ganha 1d4+1 PE temporários; se ela se provar certa no fim da missão, +1 PE máximo.', 'Arquivos Secretos 5, p. 54'),
('origem', 'Funcionário de Beira de Estrada', '{"pericias": "Fortitude e Intuição", "subtipo": "Poder: Turno Invertido"}'::jsonb, 'Uma vez por missão, recebe os benefícios de dormir no interlúdio sem dormir; +2 contra efeitos que deixam inconsciente.', 'Arquivos Secretos 5, p. 54'),
('uso_pericia', 'Rastrear Trilha Digital', '{"subtipo": "Tecnologia"}'::jsonb, 'Veterano, 1d4+1 ações completas: refaz o trajeto de um aparelho eletrônico (DT 20 a 30 conforme o caminho).', 'Arquivos Secretos 5, p. 55'),
('poder_classe', 'Aura de Confiança', '{"classe": "Combatente"}'::jsonb, 'Aliados a até 18m ganham +5 em Iniciativa e contra presença perturbadora.', 'Arquivos Secretos 5, p. 55'),
('poder_classe', 'Fôlego de Emergência', '{"classe": "Combatente"}'::jsonb, 'Uma vez por cena, machucado e com ameaça presente, movimento para recuperar 2d8+Vig PV ou 1d8+Vig PE.', 'Arquivos Secretos 5, p. 55'),
('poder_classe', 'Parede de Carne', '{"classe": "Combatente", "prerequisitos": "Vig 3 ou For 3"}'::jsonb, 'Aliados adjacentes recebem cobertura leve (+5 na Defesa).', 'Arquivos Secretos 5, p. 55'),
('poder_classe', 'Adepto do Escuro', '{"classe": "Especialista"}'::jsonb, 'Ignora camuflagem por escuridão e ganha +5 em Investigação e Percepção na penumbra.', 'Arquivos Secretos 5, p. 55'),
('poder_classe', 'Saudosista Hi-Tech', '{"classe": "Especialista"}'::jsonb, '+5 em Tecnologia com aparelhos antigos e para consertar eletrônicos; ação extra na primeira rodada de hacking.', 'Arquivos Secretos 5, p. 55'),
('poder_classe', 'Treinado nas Telas', '{"classe": "Especialista"}'::jsonb, '1 PE: soma Intelecto em Iniciativa ou Reflexos.', 'Arquivos Secretos 5, p. 55'),
('poder_classe', 'Desafiar o Ego', '{"classe": "Ocultista"}'::jsonb, 'Uma vez por rodada, reação e 3 PE: inverte um bônus ou penalidade em dados que um ser em alcance curto recebeu.', 'Arquivos Secretos 5, p. 56'),
('poder_classe', 'Catálogo de Criaturas Ambulante', '{"classe": "Ocultista", "prerequisitos": "Identificação Paranormal"}'::jsonb, 'Identifica criaturas como ação de movimento e até só por vestígios.', 'Arquivos Secretos 5, p. 56'),
('poder_classe', 'Meditação Ocultista', '{"classe": "Ocultista"}'::jsonb, 'Nova ação de interlúdio: recupera PE igual ao dobro do seu limite por turno (varia com a condição de meditação).', 'Arquivos Secretos 5, p. 56'),
