('poder_geral', 'Ruído de Comunicação', '{"prerequisitos": "Pre 2"}'::jsonb, 'Uma vez por rodada, reação e 1 PE ao ver um aliado atacar: se acertar, soma sua Presença ao dano; se errar, recupera o PE.', 'Arquivos Secretos 5, p. 56'),
('poder_geral', 'Direção Defensiva', '{}'::jsonb, 'Treino em Pilotagem (ou +2); dirigindo, todos no veículo ganham +2 na Defesa e nas resistências.', 'Arquivos Secretos 5, p. 57'),
('poder_paranormal', 'Dead Man Switch', '{"elemento": "Conhecimento", "afinidade": "Até três alvos e uma perícia a mais; se morrer, dura até o fim da missão."}'::jsonb, 'Machucado, transmite a um aliado em alcance médio o seu grau de treinamento numa perícia, até se recuperar ou morrer.', 'Arquivos Secretos 5, p. 57'),
('poder_paranormal', 'Ácido Corrosivo', '{"elemento": "Energia", "afinidade": "+4 no ataque e +10 no dano.", "prerequisitos": "Energia 1"}'::jsonb, '1 PE: na cena, +2 no ataque e +5 no dano desarmado (químico), ou numa arma que será destruída no fim da cena.', 'Arquivos Secretos 5, p. 57'),
('poder_paranormal', 'Paralinguística Ampliada', '{"elemento": "Conhecimento", "afinidade": "Bônus +10 e fica sempre sob Compreensão Paranormal verdadeira."}'::jsonb, '+5 para decifrar linguagens do Outro Lado e aprende Compreensão Paranormal (ou ele custa 1 PE a menos).', 'Arquivos Secretos 5, p. 57'),
('habilidade_trilha', 'Método Intuitivo', '{"classe": "Ocultista", "trilha": "Criptologista do Oculto", "nex": 10}'::jsonb, 'Ganha Criar Selo e cria 2 selos por ação de interlúdio (+1 por habilidade da trilha).', 'Arquivos Secretos 5, p. 58'),
('habilidade_trilha', 'Caligrafia Eficiente', '{"classe": "Ocultista", "trilha": "Criptologista do Oculto", "nex": 40}'::jsonb, 'Seus selos ficam mais fáceis de usar (Ocultismo DT 10 + custo) e +5 para identificar rituais.', 'Arquivos Secretos 5, p. 58'),
('habilidade_trilha', 'Decifrar à Distância', '{"classe": "Ocultista", "trilha": "Criptologista do Oculto", "nex": 65}'::jsonb, 'Usa selos em alcance curto só lendo mentalmente; +5 para decifrar sigilos.', 'Arquivos Secretos 5, p. 58'),
('habilidade_trilha', 'Selo Supremo', '{"classe": "Ocultista", "trilha": "Criptologista do Oculto", "nex": 99}'::jsonb, 'Seus selos dispensam Ocultismo, têm DT +5, +3 dados de dano e formas avançadas de graça.', 'Arquivos Secretos 5, p. 58'),
('origem', 'Cientista Ex-Panacea', '{"pericias": "Atualidades e Ciências", "subtipo": "Poder: Existe uma Explicação"}'::jsonb, '2 PE: usa Ciências no lugar de Ocultismo.', 'Arquivos Secretos 6, p. 66'),
('origem', 'Cobaia Sobrevivente', '{"pericias": "Fortitude e Vontade", "subtipo": "Poder: Forças para Enfrentar"}'::jsonb, 'Cenas ligadas ao seu trauma o deixam abalado, mas 2 PE dão imunidade a medo até o fim da cena.', 'Arquivos Secretos 6, p. 66'),
('origem', 'Segurança Ex-Panacea', '{"pericias": "Luta e Pontaria", "subtipo": "Poder: Técnicas de Contenção"}'::jsonb, '2 PE: +5 num teste de manobra de combate.', 'Arquivos Secretos 6, p. 67'),
('poder_classe', 'Análise Combativa', '{"classe": "Combatente", "prerequisitos": "Ciente das Cicatrizes"}'::jsonb, '+5 com Ciente das Cicatrizes e +2 contra ameaças já analisadas por ele.', 'Arquivos Secretos 6, p. 67'),
('poder_classe', 'Especialista em Proteção Leve', '{"classe": "Combatente"}'::jsonb, 'Com proteção leve, +2 na Defesa e em Reflexos.', 'Arquivos Secretos 6, p. 67'),
('poder_classe', 'Médico da Salvação', '{"classe": "Especialista", "prerequisitos": "Paramédico"}'::jsonb, 'Paramédico usa d12 e, uma vez por rodada, 3 PE para usá-lo como ação de movimento.', 'Arquivos Secretos 6, p. 68'),
('poder_classe', 'Doutor em Emergências', '{"classe": "Especialista", "prerequisitos": "Especialista em Emergências"}'::jsonb, 'Cicatrizantes e medicamentos aplicados por você curam +1d8; +5 em Medicina para tratar e o paciente ganha +10 contra a doença ou veneno.', 'Arquivos Secretos 6, p. 68'),
('poder_classe', 'Resgatar da Morte', '{"classe": "Especialista", "prerequisitos": "Veterano em Medicina"}'::jsonb, '2 PE: sucesso automático em primeiros socorros (uma vez por cena por pessoa).', 'Arquivos Secretos 6, p. 68'),
('poder_classe', 'Farmacêutico de Campo', '{"classe": "Especialista", "prerequisitos": "Treinado em Medicina e Profissão (químico)"}'::jsonb, 'No interlúdio, com kit de medicina, fabrica um cicatrizante ou medicamento pagando PE pela categoria.', 'Arquivos Secretos 6, p. 68'),
('poder_classe', 'Veterano da Equipe de Trauma', '{"classe": "Especialista", "prerequisitos": "Paramédico, Equipe de Trauma"}'::jsonb, 'Equipe de Trauma remove até três condições.', 'Arquivos Secretos 6, p. 68'),
('poder_classe', 'Barreira do Oculto', '{"classe": "Ocultista", "prerequisitos": "Especialista em Elemento no elemento, NEX 30%"}'::jsonb, 'Ao conjurar ritual do elemento, paga PE para +2 de Defesa por PE por 1 rodada.', 'Arquivos Secretos 6, p. 69'),
('poder_classe', 'Grão-Mestre em Elemento', '{"classe": "Ocultista", "prerequisitos": "Mestre em Elemento no elemento, NEX 60%"}'::jsonb, 'Ao conjurar ritual do elemento, 1 PE para um efeito extra num alvo (aliado é beneficiado, inimigo sofre uma condição), ignorando imunidades.', 'Arquivos Secretos 6, p. 69'),
('poder_geral', 'Muito Sorrateiro', '{"prerequisitos": "Sorrateiro"}'::jsonb, 'Começa cenas de furtividade com visibilidade reduzida em 1d4 e +3 em Furtividade.', 'Arquivos Secretos 6, p. 70'),
('poder_geral', 'Adaptação Climática', '{"prerequisitos": "Vig 2"}'::jsonb, '+2 em Fortitude e sem dano por calor ou frio extremos.', 'Arquivos Secretos 6, p. 70'),
('poder_geral', 'Especialista em Armas Improvisadas', '{"prerequisitos": "For 2 ou Agi 2, treinado em Luta"}'::jsonb, 'Sem penalidade com armas improvisadas e +1 dado de dano com elas.', 'Arquivos Secretos 6, p. 70'),
