('origem', 'Veterano de Conflito Armado', '{"pericias": "Luta e Pontaria", "subtipo": "Poder: Full Metal Jacket"}'::jsonb, '2 PE: ignora as penalidades num teste de Luta ou Pontaria.', 'Arquivos Secretos 9, p. 38'),
('uso_pericia', 'Analisar Perigo', '{"subtipo": "Tática"}'::jsonb, 'Treinado, DT 15, movimento, uma vez por cena: +2 em testes e na Defesa até o fim do próximo turno (+1 a cada 5 acima da DT).', 'Arquivos Secretos 9, p. 39'),
('poder_classe', 'Tática de Abordagem', '{"classe": "Combatente", "prerequisitos": "Int 1, veterano em Tática"}'::jsonb, 'Nova ação de interlúdio: planeja contra uma ameaça e ganha dados de tática (d6) para somar a testes, dano ou cura do grupo.', 'Arquivos Secretos 9, p. 39'),
('poder_classe', 'Municiador Ambulante', '{"classe": "Combatente", "prerequisitos": "Int 2"}'::jsonb, 'Nova ação de interlúdio: prepara pacotes de munição (1d6 por ponto de Int) que não ocupam espaço.', 'Arquivos Secretos 9, p. 39'),
('poder_classe', 'Ripostar Ousado', '{"classe": "Combatente", "prerequisitos": "Agi 2, treinado em Luta"}'::jsonb, 'Reação e 2 PE contra um ataque corpo a corpo: +5 na Defesa e, se ele errar, +5 no contra-ataque.', 'Arquivos Secretos 9, p. 39'),
('poder_classe', 'Tiro Intuitivo', '{"classe": "Combatente", "prerequisitos": "Veterano em Pontaria"}'::jsonb, 'Sem mirar, 2 PE: +2 na margem de ameaça do ataque à distância.', 'Arquivos Secretos 9, p. 39'),
('habilidade_trilha', 'CQB', '{"classe": "Combatente", "trilha": "Incursor", "nex": 10}'::jsonb, 'Treino em Pontaria (ou Luta, ou +2 nas duas) e 1 PE anula a penalidade contra alvo em corpo a corpo.', 'Arquivos Secretos 9, p. 40'),
('habilidade_trilha', 'Entrada Explosiva', '{"classe": "Combatente", "trilha": "Incursor", "nex": 40}'::jsonb, '+5 para usar explosivos e 1 PE para instalar mina ou carga como ação de movimento.', 'Arquivos Secretos 9, p. 40'),
('habilidade_trilha', 'Proteger Reféns', '{"classe": "Combatente", "trilha": "Incursor", "nex": 65}'::jsonb, 'Reação e 2 PE: recebe no lugar de um refém a até 3m o efeito negativo; mais 2 PE para reduzir o dano à metade.', 'Arquivos Secretos 9, p. 40'),
('habilidade_trilha', 'Alvo-prioritário', '{"classe": "Combatente", "trilha": "Incursor", "nex": 99}'::jsonb, 'Sabe o VD dos inimigos; 5 PE marca um alvo: com VD até 200, qualquer dano seu o zera; acima disso, +5 na margem.', 'Arquivos Secretos 9, p. 40'),
